const { selectedId, changes, viewAs, tocData } = options.getState();
const itemChanges = changes[selectedId];
const isItemInStore = tocData.has(selectedId);
if (!selectedId || viewAs || itemChanges || !isItemInStore) {
	return { disabled: true };
}

const { related_id: relatedId } = tocData.get(selectedId);
const relatedChanges = changes[relatedId];
const disabled = !!relatedChanges;
return { disabled };
